fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    // Problem states word is non-empty.
    let mut result = word.clone();

    // If first char is lowercase, replace it with 'A'. If uppercase, keep it.
    if matches!(result[0], 'a'..='z') {
        result[0] = 'A';
    }

    result
}

